-- Baseline: record migrations already applied to production BY HAND,
-- WITHOUT running them. Equivalent to:
--   npm run db:baseline -- --upto 0035_error_logs.sql
-- but runnable from the Railway Postgres console, which has psql but no node.
--
-- Checksums are generated by the runner's own checksumOf() (sha256 of the file
-- with CRLF normalised to LF), so they match what the container will compute.
--
-- Safe to run twice: ON CONFLICT DO NOTHING.
-- Creates NO schema and runs NONE of these migrations.

BEGIN;

CREATE TABLE IF NOT EXISTS applied_migrations (
  name        varchar(255) PRIMARY KEY,
  checksum    varchar(64)  NOT NULL,
  applied_at  timestamptz  NOT NULL DEFAULT now()
);

ON CONFLICT (name) DO NOTHING;

COMMIT;

-- Expect 36. If this is not 36, STOP and do not deploy.
SELECT count(*) AS recorded FROM applied_migrations;
